module zap_dual_rank_synchronizer (
	i_clk,
	i_reset,
	i_async,
	o_sync
);
	parameter [31:0] WIDTH = 32'd1;
	input wire i_clk;
	input wire i_reset;
	input wire [WIDTH - 1:0] i_async;
	output reg [WIDTH - 1:0] o_sync;
	reg [WIDTH - 1:0] meta;
	always @(posedge i_clk)
		if (i_reset)
			meta <= 1'sb0;
		else
			meta <= i_async;
	always @(posedge i_clk)
		if (i_reset)
			o_sync <= 1'sb0;
		else
			o_sync <= meta;
