	o_full_n
);
	parameter [31:0] WIDTH = 32'd32;
	parameter [31:0] DEPTH = 32'd32;
	input wire i_clk;
	input wire i_reset;
	input wire i_ack;
	input wire i_wr_en;
	input wire [WIDTH - 1:0] i_data;
	output wire [WIDTH - 1:0] o_data;
	input wire i_clear;
	output wire o_empty;
	output wire o_empty_n;
	output wire o_full;
	output wire o_full_n;
	localparam [31:0] PTR_WDT = $clog2(DEPTH) + 32'd1;
	reg [PTR_WDT - 1:0] rptr_ff;
	wire [PTR_WDT - 1:0] rptr_nxt;
	reg [PTR_WDT - 1:0] wptr_ff;
	wire [PTR_WDT - 1:0] wptr_nxt;
	reg empty_ff;
	wire empty_nxt;
	reg full_ff;
	wire full_nxt;
	reg [WIDTH - 1:0] mem [DEPTH - 1:0];
	wire write_ok;
	wire read_ok;
	assign o_empty = empty_ff;
	assign o_empty_n = ~o_empty;
	assign o_full_n = ~o_full;
	assign o_full = full_ff;
	assign o_data = mem[rptr_ff[PTR_WDT - 2:0]];
	assign empty_nxt = (i_clear ? 1'd1 : wptr_nxt == rptr_nxt);
	assign full_nxt = (i_clear ? 1'd0 : (wptr_nxt[PTR_WDT - 2:0] == rptr_nxt[PTR_WDT - 2:0]) & (wptr_nxt[PTR_WDT - 1] != rptr_nxt[PTR_WDT - 1]));
	always @(posedge i_clk)
		if (i_reset) begin
			empty_ff <= 1'd1;
			full_ff <= 1'd0;
		end
		else begin
			empty_ff <= empty_nxt;
			full_ff <= full_nxt;
		end
	assign write_ok = i_wr_en & ~o_full;
	assign read_ok = i_ack & ~o_empty;
	always @(posedge i_clk)
		if (write_ok)
			mem[wptr_ff[PTR_WDT - 2:0]] <= i_data;
	assign wptr_nxt = (i_clear ? 'd0 : wptr_ff + (write_ok ? 'd1 : 'd0));
	assign rptr_nxt = (i_clear ? 'd0 : rptr_ff + (read_ok ? 'd1 : 'd0));
	always @(posedge i_clk)
		if (i_reset) begin
			rptr_ff <= 1'sb0;
			wptr_ff <= 1'sb0;
		end
		else begin
			rptr_ff <= rptr_nxt;
			wptr_ff <= wptr_nxt;
		end
endmodule
