	localparam [1:0] WNT = 2'b01;
	localparam [1:0] WT = 2'b10;
	localparam [1:0] ST = 2'b11;
	localparam [31:0] ZAP_SRCDEST_EXTEND = 32'd32;
	localparam [31:0] ZAP_DP_RB_EXTEND = 32'd32;
	localparam [31:0] ZAP_BASE_EXTEND = 32'd33;
	localparam [31:0] ZAP_DP_RD_EXTEND = 32'd33;
	localparam [31:0] ZAP_DP_RA_EXTEND = 32'd34;
	localparam [31:0] ZAP_OPCODE_EXTEND = 32'd35;
	localparam [0:0] APSR_BAD = 1'd0;
	localparam [0:0] APSR_OK = 1'd1;
	wire [3:0] match;
	reg dummy;
	wire unused;
	assign unused = |dummy;
	assign match[0] = (i_sptlb_rdata[(56 - $clog2(SPAGE_TLB_ENTRIES)) - 1:36] == i_va[31:12 + $clog2(SPAGE_TLB_ENTRIES)]) && i_sptlb_rdav;
	assign match[1] = (i_lptlb_rdata[(48 - $clog2(LPAGE_TLB_ENTRIES)) - 1:32] == i_va[31:16 + $clog2(LPAGE_TLB_ENTRIES)]) && i_lptlb_rdav;
	assign match[2] = (i_setlb_rdata[(44 - $clog2(SECTION_TLB_ENTRIES)) - 1:32] == i_va[31:20 + $clog2(SECTION_TLB_ENTRIES)]) && i_setlb_rdav;
	assign match[3] = (i_fptlb_rdata[(54 - $clog2(FPAGE_TLB_ENTRIES)) - 1:32] == i_va[31:10 + $clog2(FPAGE_TLB_ENTRIES)]) && i_fptlb_rdav;
	function automatic is_apsr_ok;
		input user;
		input rd;
		input wr;
		input [3:0] apsr;
		casez (apsr)
			APSR_NA_NA: is_apsr_ok = APSR_BAD;
			APSR_RO_RO: is_apsr_ok = !wr;
			APSR_RO_NA: is_apsr_ok = !user && rd;
			APSR_RW_NA: is_apsr_ok = !user;
			APSR_RW_RO: is_apsr_ok = !user | (user && rd);
			APSR_RW_RW: is_apsr_ok = APSR_OK;
			default: is_apsr_ok = APSR_BAD;
		endcase
	endfunction
	function automatic [7:0] get_fsr_fpage;
		input user;
		input rd;
		input wr;
		input [1:0] sr;
		input [31:0] dac_reg;
		input [9:0] tlb;
		reg [3:0] apsr;
		reg [1:0] dac;
		reg unused;
		begin
			unused = |{tlb[1:0], tlb[3:2]};
			apsr[3:2] = tlb[5:4];
			dac[1:0] = dac_reg[tlb[9:6] * 2+:2];
			apsr[1:0] = sr[1:0];
			case (dac)
				DAC_MANAGER: get_fsr_fpage = 1'sb0;
				DAC_CLIENT:
					if (is_apsr_ok(user, rd, wr, apsr) == APSR_OK)
						get_fsr_fpage = 1'sb0;
					else
						get_fsr_fpage = {tlb[9:6], FSR_PAGE_PERMISSION_FAULT};
				default: get_fsr_fpage = {tlb[9:6], FSR_PAGE_DOMAIN_FAULT};
			endcase
		end
	endfunction
	function automatic [7:0] get_fsr_lpage;
		input [1:0] ap_sel;
		input user;
		input rd;
		input wr;
		input [1:0] sr;
		input [31:0] dac_reg;
		input [15:0] tlb;
		reg [3:0] apsr;
		reg [1:0] dac;
		reg [5:0] dummy;
		reg unused;
		begin
			unused = |{dummy, tlb[1:0], tlb[3:2]};
			{dummy, apsr[3:2]} = tlb[11:4] >> ({30'd0, ap_sel} << 32'd1);
			dac[1:0] = dac_reg[tlb[15:12] * 2+:2];
			apsr[1:0] = sr[1:0];
			case (dac)
				DAC_MANAGER: get_fsr_lpage = 1'sb0;
				DAC_CLIENT:
					if (is_apsr_ok(user, rd, wr, apsr) == APSR_OK)
						get_fsr_lpage = 1'sb0;
					else
						get_fsr_lpage = {tlb[15:12], FSR_PAGE_PERMISSION_FAULT};
				default: get_fsr_lpage = {tlb[15:12], FSR_PAGE_DOMAIN_FAULT};
			endcase
		end
	endfunction
	function automatic [7:0] get_fsr_section;
		input user;
		input rd;
		input wr;
		input [1:0] sr;
		input [31:0] dac_reg;
		input [19:0] tlb;
		reg [3:0] apsr;
		reg [1:0] dac;
		reg unused;
		begin
			unused = |{tlb[19:12], tlb[9], tlb[4], tlb[3:2]};
			apsr[3:2] = tlb[11:10];
			dac[1:0] = dac_reg[tlb[8:5] * 2+:2];
			apsr[1:0] = sr[1:0];
			if (tlb[1:0] == 2'b00)
				get_fsr_section = {tlb[8:5], FSR_SECTION_TRANSLATION_FAULT};
			else if (tlb[1:0] == 2'b11)
				get_fsr_section = {tlb[8:5], FSR_L1_EXTERNAL_ABORT};
			else
				case (dac)
					DAC_MANAGER: get_fsr_section = 1'sb0;
					DAC_CLIENT:
						if (is_apsr_ok(user, rd, wr, apsr) == APSR_OK)
							get_fsr_section = 1'sb0;
						else
							get_fsr_section = {tlb[8:5], FSR_SECTION_PERMISSION_FAULT};
					default: get_fsr_section = {tlb[8:5], FSR_SECTION_DOMAIN_FAULT};
				endcase
		end
	endfunction
	function automatic [7:0] get_fsr_spage;
		input [1:0] ap_sel;
		input user;
		input rd;
		input wr;
		input [1:0] sr;
		input [31:0] dac_reg;
		input [15:0] tlb;
		reg [3:0] apsr;
		reg [1:0] dac;
		reg [5:0] unused;
		begin
			{unused, apsr[3:2]} = tlb[11:4] >> ({30'd0, ap_sel} << 32'd1);
			dac[1:0] = dac_reg[tlb[15:12] * 2+:2];
			apsr[1:0] = sr[1:0];
			unused[1:0] = unused[1:0] | tlb[3:2];
			if (tlb[1:0] == 2'b00)
				get_fsr_spage = {tlb[15:12], FSR_PAGE_TRANSLATION_FAULT};
			else if (tlb[1:0] == 2'b11)
				get_fsr_spage = {tlb[15:12], FSR_L2_EXTERNAL_ABORT};
			else
				case (dac)
					DAC_MANAGER: get_fsr_spage = 1'sb0;
					DAC_CLIENT:
						if (is_apsr_ok(user, rd, wr, apsr) == APSR_OK)
							get_fsr_spage = 1'sb0;
						else
							get_fsr_spage = {tlb[15:12], FSR_PAGE_PERMISSION_FAULT};
					default: get_fsr_spage = {tlb[15:12], FSR_PAGE_DOMAIN_FAULT};
				endcase
		end
	endfunction
	always @(posedge i_clk)
		if (i_clkena) begin : tlb_match_logic
			dummy <= 1'd0;
			o_fsr <= 0;
			o_far <= i_va;
			o_phy_addr <= i_va;
			o_walk <= 0;
			o_cacheable <= MMU_OFF_CACHEABLE;
			o_wt <= 0;
			if (i_mmu_en && (i_rd || i_wr))
				case (match[3:0])
					4'b0001: begin
						o_fsr <= get_fsr_spage(i_va[11:10], i_cpsr[ZAP_CPSR_MODE:0] == USR, i_rd, i_wr, i_sr, i_dac_reg, i_sptlb_rdata[15:0]);
						o_phy_addr <= {i_sptlb_rdata[35:16], i_va[11:0]};
						{dummy, o_cacheable} <= i_sptlb_rdata[3:2] >> 1;
						o_wt <= i_sptlb_rdata[3:2] == 2'b10;
					end
					4'b0010: begin
						o_fsr <= get_fsr_lpage(i_va[15:14], i_cpsr[ZAP_CPSR_MODE:0] == USR, i_rd, i_wr, i_sr, i_dac_reg, i_lptlb_rdata[15:0]);
						o_phy_addr <= {i_lptlb_rdata[31:16], i_va[15:0]};
						{dummy, o_cacheable} <= i_lptlb_rdata[3:2] >> 1;
						o_wt <= i_lptlb_rdata[3:2] == 2'b10;
					end
					4'b0100: begin
						o_fsr <= get_fsr_section(i_cpsr[ZAP_CPSR_MODE:0] == USR, i_rd, i_wr, i_sr, i_dac_reg, i_setlb_rdata[19:0]);
						o_phy_addr <= {i_setlb_rdata[31:20], i_va[19:0]};
						{dummy, o_cacheable} <= i_setlb_rdata[3:2] >> 1;
						o_wt <= i_setlb_rdata[3:2] == 2'b10;
					end
					4'b1000: begin
						o_fsr <= get_fsr_fpage(i_cpsr[ZAP_CPSR_MODE:0] == USR, i_rd, i_wr, i_sr, i_dac_reg, i_fptlb_rdata[9:0]);
						o_phy_addr <= {i_fptlb_rdata[31:10], i_va[9:0]};
						{dummy, o_cacheable} <= i_fptlb_rdata[3:2] >> 1;
						o_wt <= i_fptlb_rdata[3:2] == 2'b10;
					end
					4'b0000: o_walk <= 1'd1;
					default: begin
						o_fsr <= 1'sbx;
						o_phy_addr <= 1'sbx;
						o_walk <= 1'sbx;
						o_far <= 1'sbx;
						o_cacheable <= 1'sbx;
						o_wt <= 1'sbx;
					end
				endcase
		end
endmodule
